head.script:
scwin.init = function() {
    pageList.setCount(100, true);
};
scwin.unitTest = function() {
    //init
    // WebSquare.wUnit.start();
    //Test step 1. 샘플실행 후 '다음페이지'버튼을 클릭한다.
    //1. After running the sample, click the 'Next Page' button.
    //Verify step 1. It is changed to 2 pages and is shown.
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('pageList_next_btn').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getObjById('pageList_input').value == '2'", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Test step 2. '마지막페이지'버튼을 클릭한다.
    //2. Click the 'Last Page' button.
    //Verify step 2. It is changed to 100 pages and it is displayed.
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('pageList_nextPage_btn').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getObjById('pageList_input').value == '100'", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Test step 3. '이전페이지'버튼을 클릭한다.
    //3. Click the 'Previous Page' button.
    //Verify step 3. It is changed to 99page and it is displayed.
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('pageList_prev_btn').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getObjById('pageList_input').value == '99'", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Test step 4. '첫페이지'버튼을 클릭한다.
    //4. Click the 'First Page' button.
    //Verify step 4. It is changed to 1 page and it is shown.
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('pageList_prevPage_btn').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getObjById('pageList_input').value == '1'", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run  and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    scwin.init();
    //Function 
    //Created by: Thuyet.Pham
    //Created date: 02-Mar-2018
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
